module max_sum (\n    input [2:0] n,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    output reg [9:0] result\n);\n\n    wire [7:0] arr [0:6];\n    assign arr[0] = arr_0;\n    assign arr[1] = arr_1;\n    assign arr[2] = arr_2;\n    assign arr[3] = arr_3;\n    assign arr[4] = arr_4;\n    assign arr[5] = arr_5;\n    assign arr[6] = arr_6;\n\n    wire [2:0] num_elements = (n << 1) - 3'd1;  // 2n-1\n\n    integer i;\n    reg [9:0] sum_abs;\n    reg [2:0] neg_count;\n    reg zero_exists;\n    reg [7:0] min_abs;\n    reg [7:0] abs_val_reg;\n\n    always @(*) begin\n        sum_abs = 10'd0;\n        neg_count = 3'd0;\n        zero_exists = 1'b0;\n        min_abs = 8'hFF;\n\n        for (i = 0; i < 7; i = i + 1) begin\n            if (i < num_elements) begin\n                abs_val_reg = arr[i][7] ? (~arr[i] + 8'd1) : arr[i];\n                neg_count = neg_count + (arr[i][7] ? 3'd1 : 3'd0);\n                zero_exists = zero_exists | (arr[i] == 8'd0);\n                sum_abs = sum_abs + {2'b00, abs_val_reg};\n                if (abs_val_reg < min_abs) min_abs = abs_val_reg;\n            end\n        end\n    end\n\n    wire is_odd = n[0];  // LSB indicates odd/even\n\n    always @(*) begin\n        if (is_odd) begin\n            result = sum_abs;\n        end else begin\n            if ((neg_count[0] == 1'b0) || zero_exists) begin\n                result = sum_abs;\n            end else begin\n                result = sum_abs - {1'b0, min_abs, 1'b0};  // 2*min_abs\n            end\n        end\n    end\n\nendmodule